/**
 * Write `src/lib/guides/meta.generated.ts` from the guides catalogue.
 *
 *   pnpm guides:meta
 *
 * Run it after any change to a guide's slug, title, description, keywords
 * or first tool. `src/lib/guides/meta.generated.test.ts` fails until you do:
 * it compares the generated file with a fresh projection of the catalogue.
 * The output is formatted with the repo's own Prettier config, so
 * `pnpm format:check` agrees with the file this writes.
 */
import { writeFileSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { format, resolveConfig } from "prettier";
import { guides } from "../src/lib/guides/catalog";
import { projectGuideMeta } from "../src/lib/guides/meta";

export const GUIDE_META_FILE = path.join(
  process.cwd(),
  "src",
  "lib",
  "guides",
  "meta.generated.ts",
);

export async function writeGuideMeta(file = GUIDE_META_FILE): Promise<number> {
  const meta = projectGuideMeta(guides);
  const source = [
    "// GENERATED by `pnpm guides:meta` (scripts/generate-guide-meta.ts) from",
    "// src/lib/guides/catalog.ts. Do not edit: meta.generated.test.ts fails on",
    "// any difference from a fresh projection of the catalogue.",
    'import type { GuideMeta } from "./meta";',
    "",
    `export const GUIDE_META: readonly GuideMeta[] = ${JSON.stringify(meta, null, 2)};`,
    "",
  ].join("\n");
  const options = (await resolveConfig(file)) ?? {};
  writeFileSync(file, await format(source, { ...options, filepath: file }));
  return meta.length;
}

const invokedDirectly =
  process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(process.argv[1]).href;
if (invokedDirectly) {
  writeGuideMeta().then(
    (count) => {
      process.stdout.write(
        `guides:meta: wrote ${count} guides to ${path.relative(process.cwd(), GUIDE_META_FILE)}\n`,
      );
    },
    (error: unknown) => {
      process.stderr.write(`guides:meta: ${(error as Error).message}\n`);
      process.exit(1);
    },
  );
}
